const STORAGE='royesh-strategy-v1';
export const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=1)=>v===null||!Number.isFinite(v)?'—':Number(v).toLocaleString(locale(),{maximumFractionDigits:d});
const pct=v=>v===null?'—':n(v*100)+'٪';
const paths={moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',home:'M3 11 12 3l9 8M5 10v10h5v-6h4v6h5V10',route:'M5 4a2 2 0 1 0 0 .1M19 20a2 2 0 1 0 0 .1M7 4h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h9',building:'M4 21V3h11v18M15 9h5v12M8 7h3M8 11h3M8 15h3M8 21v-3h3v3',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',radar:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12 21 3',layers:'m12 3 10 6-10 6L2 9 12 3M2 13l10 6 10-6M2 17l10 6 10-6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',branch:'M6 3v12a4 4 0 0 0 4 4h8M6 8h8a4 4 0 0 0 4-4M3 3h6M15 3h6M15 19h6',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',chart:'M4 20h17M7 16v-5M12 16V7M17 16V3',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-5-5-3 6-6 3 3-6 6-3',kanban:'M3 3h18v18H3zM8 3v18M16 3v18M5 7h1M10 7h4M18 7h1M10 12h4',activity:'M2 12h4l3-8 6 16 3-8h4',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4M8 12l3 3 5-6',book:'M12 5v16M12 5C9 3 5 3 2 5v15c3-2 7-2 10 1 3-3 7-3 10-1V5c-3-2-7-2-10 0',file:'M14 2H5v20h14V7l-5-5M14 2v6h5M8 12h8M8 16h8',cap:'m12 3 11 6-11 6L1 9l11-6M5 12v6c4 3 10 3 14 0v-6M23 9v8',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M4 17h16l-2-3V9a6 6 0 0 0-12 0v5l-2 3M10 21h4',down:'m6 9 6 6 6-6',left:'m14 5-7 7 7 7M7 12h14',plus:'M12 4v16M4 12h16',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',edit:'m15 4 5 5M3 21l5-1L21 7l-5-5L3 15v6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',link:'m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,route,cls='text-btn')=>`<a class="${cls}" href="#${route}">${label}</a>`;
const hint=key=>!state.learning?'':`<button class="help-btn ${state.learning?'':'hidden-help'}" data-help="${key}" aria-label="توضیح ${e(help[key]?.title||key)}" aria-haspopup="dialog">!</button>`;
const pill=(label,type='')=>`<span class="pill ${type}">${e(label)}</span>`;
const statusPill=s=>pill(s,s==='تکمیل‌شده'||s==='ثبت‌شده'?'green':s==='در اجرا'||s==='در حال آزمون'?'blue':'orange');
const guide=(text,type='')=>`<div class="guide ${type||'educational'}">${icon(type==='error'?'shield':'cap')}<div>${text}</div></div>`;
const field=(label,key,value,type='text',extra='')=>`<label class="field"><span>${label}</span><${type==='textarea'?'textarea':'input'} name="${e(key)}" ${['text','textarea'].includes(type)?`data-canonical="${e(value)}"`:''} ${type!=='textarea'?`type="${type}" value="${e(type==='text'?translate(value):value)}"`:''} ${extra}>${type==='textarea'?e(translate(value)):''}${type==='textarea'?'</textarea>':''}</label>`;
const options=(vals,selected)=>vals.map(v=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(v)}</option>`).join('');
const select=(label,key,vals,value)=>`<label class="field"><span>${label}</span><select name="${e(key)}">${options(vals,value)}</select></label>`;
const progressBar=value=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;
function validateState(s) {
  const seed=createSeed();
  if(!s || s.version!==1 || Object.keys(seed).some(key=>!(key in s))) return false;
  if(!s.org || typeof s.org.name!=='string' || Object.values(s.org).some(v=>typeof v!=='string'&&typeof v!=='number')) return false;
  for(const key of ['external','internal','objectives','initiatives','risks','journal','pestel','competitors','vrio','swot','options','products']) {
    if(!Array.isArray(s[key])||s[key].length>200||s[key].some(r=>!r||typeof r.id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(r.id)||typeof(r.title??r.name)!=='string')) return false;
    const required=Object.entries(seed[key][0]).filter(([field])=>!['source','confidence'].includes(field));
    if(s[key].some(r=>required.some(([field,example])=>typeof r[field]!==typeof example||(typeof example==='number'&&!Number.isFinite(r[field])))))return false;
    if(new Set(s[key].map(r=>r.id)).size!==s[key].length)return false;
  }
  for(const key of ['external','internal']) if(!s[key].length||s[key].some(r=>!Number.isFinite(r.weight)||!Number.isFinite(r.rating)||r.weight<0||r.weight>100||r.rating<1||r.rating>4)) return false;
  if(Object.keys(seed.fin).some(key=>!Number.isFinite(s.fin?.[key]))||!Array.isArray(s.investment?.flows)||s.investment.flows.some(v=>!Number.isFinite(v))) return false;
  if(!Array.isArray(s.trend?.revenue)||!Array.isArray(s.trend?.target)||!Array.isArray(s.trend?.months)||s.trend.revenue.length!==s.trend.months.length||s.trend.target.length!==s.trend.months.length||s.trend.revenue.some(v=>!Number.isFinite(v))||s.trend.target.some(v=>!Number.isFinite(v))) return false;
  if(!Array.isArray(s.completed)||s.completed.length!==6||s.completed.some(v=>typeof v!=='boolean')||!Array.isArray(s.forces)||s.forces.length!==5||s.forces.some(v=>!Number.isFinite(v)||v<1||v>5))return false;
  for(const key of ['FS','IS','CA','ES']) if(!Array.isArray(s.space?.[key])||s.space[key].length!==3||s.space[key].some(v=>!Number.isFinite(v)||v<(key==='FS'||key==='IS'?1:-6)||v>(key==='FS'||key==='IS'?6:-1)))return false;
  if(typeof s.qScores!=='object'||!s.qScores)return false;
  for(const r of [...s.external,...s.internal]) if(!s.qScores[r.id]||typeof s.qScores[r.id].relevant!=='boolean'||!Array.isArray(s.qScores[r.id].as)||s.qScores[r.id].as.length!==3||s.qScores[r.id].as.some(v=>!Number.isFinite(v)||v<1||v>4))return false;
  if(!Number.isFinite(s.scenario?.growth)||!Number.isFinite(s.scenario?.inflation)||!Number.isFinite(s.bcgThreshold)||typeof s.notes!=='string'||typeof s.learning!=='boolean'||!['company','startup'].includes(s.mode)||!['six','quarter','month'].includes(s.period))return false;
  return s.options.length===3 && s.objectives.every(o=>[o.baseline,o.actual,o.target].every(Number.isFinite)) && s.products.every(p=>[p.share,p.growth,p.revenue,p.attraction,p.strength].every(Number.isFinite)&&p.share>0&&p.revenue>=0)&&s.risks.every(r=>Number.isFinite(r.probability)&&Number.isFinite(r.impact)&&r.probability>=1&&r.probability<=5&&r.impact>=1&&r.impact<=5);
}
let state=createSeed(),storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(validateState(saved))state=saved;}catch{storageAvailable=false;}
let view='overview',sub='',modalTrigger=null,installPrompt=null,tooltipKey=null;
const matrixNames={efe:'عوامل خارجی · EFE',ife:'عوامل داخلی · IFE',cpm:'پروفایل رقابتی · CPM',space:'جهت‌گیری · SPACE',bcg:'سبد کسب‌وکار · BCG',ie:'داخلی–خارجی · IE',ge:'جذابیت و قدرت · GE',ansoff:'مسیر رشد · Ansoff',grand:'استراتژی اصلی'};
const conceptRoutes={icp:'company',roa:'finance',roe:'finance',npv:'finance',irr:'finance',cac:'finance',ltv:'finance',cagr:'finance',margin:'finance',efe:'matrices/efe',ife:'matrices/ife',bcg:'matrices/bcg',space:'matrices/space',ie:'matrices/ie',qspm:'qspm',bsc:'scorecard',vrio:'internal',porter:'industry',risk:'risks',scenario:'scenarios',progress:'scorecard'};
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageAvailable=false;toast('ذخیره مرورگر در دسترس نیست؛ پشتیبان JSON بگیرید.');}};
function toast(text){const node=document.createElement('div');node.className='toast';node.textContent=translate(text);localize(node);document.querySelector('#toasts').append(node);setTimeout(()=>node.remove(),4500);}
const heading=(title,desc,actions='')=>`<header class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${state.learning&&tourAvailable(view,sub)?button(icon('cap')+' آموزش این صفحه','tour','tour-trigger'):''}${actions}</div></header>`;
const panel=(title,body,action='',key='')=>`<section class="panel"><div class="section-heading"><h2 class="panel-title">${title} ${key?hint(key):''}</h2>${action}</div>${body}</section>`;
const spark=(values)=>`<svg class="spark" viewBox="0 0 70 25" aria-hidden="true"><path d="${values.map((v,i)=>`${i?'L':'M'}${i*12} ${25-v}`).join(' ')}" fill="none" stroke="#8bb3a1" stroke-width="2"/></svg>`;
const metric=(title,value,unit,foot,key='',delta='')=>`<div class="metric"><div class="metric-top">${title} ${key?hint(key):''}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-bottom"><span>${delta?`<span class="delta">${delta}</span> `:''}${foot}</span>${spark([4,10,8,16,14,22])}</div></div>`;
function journeyStrip(){const current=state.completed.findIndex(v=>!v);return `<div class="journey-strip">${stages.map((s,i)=>`<a href="#${s.route}" class="journey-step ${state.completed[i]?'done':i===current?'current':''}"><span class="step-circle">${state.completed[i]?'✓':n(i+1)}</span>${s.title}</a>`).join('')}</div>`;}
const listLink=(title,desc,route,ico='target',color='blue')=>`<a class="list-row" href="#${route}"><span class="number-chip ${color}">${icon(ico)}</span><div><strong>${title}</strong><p>${desc}</p></div>${icon('left')}</a>`;
function overview(){const f=financials(state.fin),done=sum(state.completed.map(Number)),current=Math.max(0,state.completed.findIndex(v=>!v));const trendStart=state.period==='quarter'?3:state.period==='month'?4:0;const t=state.trend;const riskCount=state.risks.filter(r=>r.probability*r.impact>=16&&r.status!=='بسته').length;const decisionScores=qspm(state.external,state.internal,state.qScores);
  return heading('سلام حمیدرضا، وقت رشد است.',`تصویر امروز ${e(state.org.name)}؛ از تحلیل‌های پراکنده به انتخاب‌های روشن.`,button(icon('download')+' گزارش مدیریتی','report')+link(icon('plus')+' ثبت تصمیم','journal','btn primary'))+
  `<section class="strategy-banner"><div><div class="eyeline">${icon('compass')} قدم پیشنهادی بعدی ${pill(`مرحله ${n(current+1)} از ۶`,'blue')}</div><h2>${state.completed.every(Boolean)?'چرخه بعدی استراتژی را با بازبینی شروع کنید.':stages[current].deliverable}</h2><p>مسیر شما آماده است. هر تحلیل را به یک انتخاب، هر انتخاب را به یک اقدام و هر اقدام را به یک نتیجه وصل کنید.</p><div class="flex">${link('ادامه مسیر '+icon('left'),state.completed.every(Boolean)?'scorecard':stages[current].route,'btn primary')}${link('دیدن نقشه راه','journey','btn')}</div></div><div class="banner-art">${strategyIllustration()}</div></section>`+
  journeyStrip()+`<div class="grid cols-4">${metric('فروش ماه نمونه',n(state.fin.revenue),'میلیون تومان','هدف '+n(t.target.at(-1)),'margin',pct(ratio(t.revenue.at(-1)-t.revenue.at(-2),t.revenue.at(-2))))}${metric('حاشیه سود ناخالص',pct(f.grossMargin),'','پس از بهای کالا','margin')}${metric('بازده دارایی ماهانه',pct(f.roa),'','دوره مالی: مهر نمونه','roa')}${metric('مرحله‌های تکمیل‌شده',n(done)+' از ۶','','خوداظهاری تیم؛ نه نمره علمی','progress')}</div>`+
  `<div class="grid wide-left mt">${panel('روند فروش و هدف',`<div class="chart-total"><strong>${n(sum(t.revenue.slice(trendStart)))}</strong><span>میلیون تومان در بازه انتخابی</span></div><div class="chart-legend"><span><i class="dot"></i>عملکرد نمونه</span><span><i class="dot gray"></i>هدف نمونه</span></div>${lineChart(t.months.slice(trendStart),t.revenue.slice(trendStart),t.target.slice(trendStart))}`,`<select class="period" aria-label="بازه نمودار" style="width:108px" data-setting="period">${options(['six','quarter','month'],state.period).replace('>six<','>۶ ماه اخیر<').replace('>quarter<','>۳ ماه اخیر<').replace('>month<','>۲ ماه اخیر<')}</select>`)}${panel('اهداف در یک نگاه',state.objectives.map(o=>`<div class="goal-row"><div class="flex between"><a href="#scorecard"><h3>${e(o.title)}</h3></a><strong class="small">${n(progress(o.actual,o.baseline,o.target))}٪</strong></div>${progressBar(progress(o.actual,o.baseline,o.target))}<div class="flex between mt" style="margin-top:5px"><small>${e(o.metric)}</small><small>${n(o.actual)} / ${n(o.target)}</small></div></div>`).join(''),link('همه اهداف','scorecard'))}</div>`+
  `<div class="grid cols-3 mt">${panel('امروز به این‌ها توجه کنید',listLink(`${n(riskCount)} ریسک با اولویت بالا`,'قیمت مواد اولیه و وصول مطالبات','risks','shield','red')+listLink('مقایسه سه مسیر رشد','از نظر جذابیت و منابع موردنیاز','qspm')+listLink('فرضیه‌های نیازمند شاهد','پیش از تعهد به توسعه بازار','journal','book','orange'))}${panel('برنامه این هفته',state.initiatives.filter(p=>p.status!=='تکمیل‌شده').slice(0,3).map(p=>`<div class="next-task"><a href="#execution"><h3>${e(p.title)}</h3></a><div class="flex between"><span>${e(p.owner)}</span>${statusPill(p.status)}</div></div>`).join(''),link('دیدن برنامه','execution'))}${panel('تصمیم روشن‌تر، قدم کوچک‌تر',`<p class="small">پیشنهاد نمونه: ابتدا فروش سازمانی را در مقیاس کوچک آزمایش کنید؛ سپس براساس وصول و سود، رشد را توسعه دهید.</p>${decisionScores?bars(state.options.map(o=>o.title),decisionScores):guide('وزن‌ها معتبر نیستند؛ ابتدا EFE و IFE را اصلاح کنید.','error')}${link('باز کردن اتاق تصمیم '+icon('left'),'qspm')}<div class="mini-learn">${icon('cap')}<div><h3>عدد، پایان تحلیل نیست</h3><p>امتیاز QSPM جذابیت نسبی را نشان می‌دهد، نه تضمین موفقیت.</p>${button('این مفهوم را یاد بگیرم','help','small', 'data-key="qspm"')}</div></div>`,'','qspm')}</div>`;
}
function journey(){return heading('هر قدم، یک خروجی روشن.','این مسیر راهنمای کار است؛ فرایند واقعی می‌تواند رفت‌وبرگشتی باشد. هیچ مرحله‌ای قفل نیست.',button('شروع دوباره مسیر','restartJourney'))+guide(state.mode==='startup'?'مسیر ساده استارتاپ: با یک بخش مشتری، ۵ مصاحبه، ۳ فرضیه و یک پایلوت کم‌هزینه شروع کنید. پیش از ماتریس‌های بزرگ، تناسب مسئله و راه‌حل و نقدینگی را بیازمایید.':'برای استارتاپ‌ها، تحلیل‌ها را با مقیاس مسئله ساده کنید. تکمیل مرحله فقط ثبت وضعیت توسط شماست؛ به معنی تأیید علمی نیست.')+`<section class="panel flat">${stages.map((s,i)=>`<div class="road-card ${state.completed[i]?'done':''}"><div class="road-icon">${state.completed[i]?icon('check'):n(i+1)}</div><div><h2>${s.title}</h2><p>${s.text}</p><small>خروجی: ${s.deliverable}</small></div><div class="flex wrap">${link('باز کردن',s.route,'btn small')}${button(state.completed[i]?'بازگرداندن وضعیت':'ثبت تکمیل','complete','small '+(state.completed[i]?'':'soft'),`data-index="${i}"`)}</div></div>`).join('')}</section>`;}
function company(){return heading('اول، مسئله درست را تعریف کنید.','جهت شرکت، مشتری هدف و مرز انتخاب‌ها؛ پایه تمام تحلیل‌های بعدی.',button('ویرایش شناخت شرکت','companyEdit','primary'))+journeyStrip()+`<div class="grid wide-left">${panel('مسئله محوری',`<h2 style="font-size:20px;color:#365786;margin-bottom:17px">${e(state.org.challenge)}</h2><div class="grid cols-2"><div><h3>مأموریت</h3><p class="small mt">${e(state.org.mission)}</p></div><div><h3>چشم‌انداز</h3><p class="small mt">${e(state.org.vision)}</p></div></div><div class="mt"><h3>مشتری هدف ${hint('icp')}</h3><p class="small" data-tour="icp">${e(state.org.customer)}</p></div><div class="mt"><h3>آگاهانه چه کار نمی‌کنیم؟</h3><p class="small">${e(state.org.notDoing)}</p></div>`)}${panel('شناسنامه نمونه',`<div class="list-row"><div><p>نام شرکت</p><strong>${e(state.org.name)}</strong></div></div><div class="list-row"><div><p>حوزه فعالیت</p><strong>${e(state.org.industry)}</strong></div></div><div class="list-row"><div><p>اعضای تیم</p><strong>${n(state.org.employees)} نفر</strong></div></div><div class="list-row"><div><p>ارزش‌ها</p><strong>${e(state.org.values)}</strong></div></div>${guide('این شرکت و همه داده‌هایش فرضی‌اند. برای کار واقعی، شواهد و تعریف صنعت را جایگزین کنید.')}`)}</div><div class="mt">${panel('بوم مدل کسب‌وکار · خلاصه نمونه',`<div class="grid cols-3">${[['ارزش پیشنهادی','میان‌وعده سالم با کیفیت قابل‌رهگیری'],['بخش مشتری','منابع انسانی سازمان‌ها و مشتری آنلاین'],['کانال','وب‌سایت مستقیم و فروش سازمانی'],['فعالیت کلیدی','تأمین، کنترل کیفیت و شخصی‌سازی'],['منابع و شرکا','تیم، داده مشتری، تأمین‌کنندگان و ارسال'],['درآمد و هزینه','فروش بسته؛ مواد اولیه، بسته‌بندی و عملیات']].map(([t,d])=>`<div class="outline-card"><h3>${t}</h3><p class="small mt">${d}</p></div>`).join('')}</div>`)}</div><div class="mt flex between">${link('قدم بعد: محیط و بازار '+icon('left'),'environment','btn primary')}${button('ثبت تکمیل شناخت','complete','', 'data-index="0"')}</div>`;}
function environment(){return heading('بیرون از شرکت چه خبر است؟','از محیط کلان به عامل مشخص، شاهد و اثر بر تصمیم برسید.',button(icon('plus')+' عامل جدید','add','primary','data-collection="pestel"'))+guide('PESTEL کیفی است. اثر ۱ تا ۵ در این رابط، مقیاس داخلی کارگاه است؛ جای داده واقعی و تحلیل روند را نمی‌گیرد.')+`<div class="grid cols-3">${state.pestel.map(p=>`<article class="panel"><div class="flex between"><span class="number-chip blue">${icon('globe')}</span>${pill(p.type,p.type==='فرصت'?'green':'orange')}</div><h2 class="mt">${e(p.category)}</h2><p class="small mt">${e(p.title)}</p><div class="flex between mt"><span class="small muted">اثر: ${n(p.impact)} از ۵</span>${button(icon('edit')+' ویرایش','edit','small',`data-collection="pestel" data-id="${e(p.id)}"`)}</div><p class="small mt">${e(p.source)}</p></article>`).join('')}</div><div class="grid cols-2 mt">${panel('اندازه بازار · برآورد نمونه',bars(['TAM · کل بازار','SAM · قابل‌خدمت','SOM · قابل‌دستیابی'],[120000,36000,3600])+'<p class="small">واحد: میلیون تومان در سال. SOM از ظرفیت فروش و وصول تخمین زده شده؛ هدف اثبات‌شده نیست.</p>')}${panel('از رصد به اقدام',listLink('وزن‌دهی عوامل بیرونی','تبدیل فرصت و تهدید به EFE','matrices/efe')+listLink('فشارهای صنعت','تحلیل پنج نیروی پورتر','industry')+listLink('اگر آینده تغییر کند؟','سناریو، محرک و پاسخ','scenarios'))}</div>`;}
function industry(){const labels=['رقابت','خریداران','تأمین‌کننده','تازه‌واردها','جایگزین‌ها'];const factors=[['quality','کیفیت',25],['price','قیمت',15],['brand','برند',20],['delivery','تحویل',15],['data','داده مشتری',10],['corporate','فروش سازمانی',15]];const scores=state.competitors.map(c=>sum(factors.map(([k,,w])=>c[k]*w/100)));
  return heading('رقابت، فقط رقیب مستقیم نیست.','تعریف صنعت نمونه: فروش میان‌وعده سالم و بسته سازمانی در بازار هدف.',link('ماتریس CPM','matrices/cpm','btn'))+guide('شدت نیروها ۱=کم تا ۵=زیاد است. نمودار، خلاصه قضاوت کارگاهی است؛ جذابیت صنعت با یک جمع عددی استاندارد تعیین نمی‌شود.')+`<div class="grid cols-2">${panel('ساختار صنعت',radar(labels,state.forces),'','porter')}${panel('شدت نیروها',labels.map((label,i)=>`<label class="field"><span>${label}<strong style="margin-right:auto">${n(state.forces[i])} از ۵</strong></span><input type="range" min="1" max="5" step="1" value="${state.forces[i]}" data-force="${i}" aria-label="شدت ${label}"></label>`).join('')+'<p class="small">هر تغییر ذخیره و نمودار به‌روز می‌شود. فرضیه محوری: کاهش وابستگی تأمین، مهم‌تر از جنگ قیمت است.</p>')}</div><div class="mt">${panel('مقایسه رقبا',bars(state.competitors.map(c=>c.name),scores,undefined,4)+`<div class="table-wrap"><table class="data-table"><thead><tr><th>شرکت فرضی</th>${factors.map(([,t,w])=>`<th>${t} · ${n(w)}٪</th>`).join('')}<th>امتیاز</th></tr></thead><tbody>${state.competitors.map((c,i)=>`<tr><td>${e(c.name)}</td>${factors.map(([k])=>`<td><input type="number" min="1" max="4" step="1" value="${c[k]}" data-competitor="${c.id}" data-field="${k}" aria-label="${e(c.name)} ${k}"></td>`).join('')}<td>${n(scores[i],2)}</td></tr>`).join('')}</tbody></table></div><p class="small mt">CPM: همان عوامل و وزن‌ها برای همه رقبا، رتبه ۱ تا ۴؛ این عوامل انتخاب داخلی نمونه‌اند.</p>`)}</div>`;
}
function internal(){return heading('روی چه قابلیتی می‌توانیم حساب کنیم؟','منابع را با شاهد بسنجید؛ هر قابلیت مهم الزاماً مزیت رقابتی نیست.',link('ارزیابی IFE','matrices/ife','btn primary'))+guide('پاسخ‌های VRIO با لمس هر خانه تغییر می‌کنند. چهار بله: کاندیدای مزیت پایدار؛ بدون آمادگی سازمان، مزیت قابل بهره‌برداری نیست.')+panel('ارزیابی منابع · VRIO',`<div class="table-wrap"><table class="data-table"><thead><tr><th>منبع / قابلیت</th><th>ارزشمند</th><th>کمیاب</th><th>تقلید دشوار</th><th>سازمان آماده</th><th>جمع‌بندی</th></tr></thead><tbody>${state.vrio.map(r=>`<tr><td>${e(r.title)}</td>${['v','r','i','o'].map(k=>`<td>${button(r[k]?'بله':'خیر','vrio','small '+(r[k]?'soft':''),`data-id="${r.id}" data-field="${k}" aria-label="${e(r.title)} ${k}: ${r[k]?'بله':'خیر'}"`)}</td>`).join('')}<td>${pill(!r.v?'بدون مزیت':!r.r?'برابری رقابتی':!r.i?'مزیت موقت':!r.o?'نیاز به سازمان‌دهی':'کاندیدای مزیت پایدار',r.v&&r.r&&r.i&&r.o?'green':'orange')}</td></tr>`).join('')}</tbody></table></div>`,'','vrio')+`<div class="mt">${panel('زنجیره ارزش · نقاط اثرگذاری',`<div class="value-chain">${[['تأمین','کیفیت و تاب‌آوری'],['عملیات','رهگیری و بسته‌بندی'],['توزیع','زمان و هزینه تحویل'],['فروش','پیشنهاد ارزش'],['خدمات','تکرار و اعتماد']].map(([t,d])=>`<div><strong>${t}</strong><span>${d}</span></div>`).join('')}</div><div class="guide mt">فعالیت‌های پشتیبان: زیرساخت، منابع انسانی، فناوری و تدارکات. هزینه و تمایز را در هر فعالیت تحلیل کنید.</div>`)}</div>`;}
function matrixIndex(){return heading('یک سؤال. یک ابزار مناسب.','به‌جای اجرای همه مدل‌ها، ابزار متناسب با مسئله را انتخاب کنید.',link('راهنمای انتخاب ابزار','learn','btn'))+`<div class="grid cols-3">${Object.entries(matrixNames).map(([key,title],i)=>`<article class="panel tool-card"><div class="flex between"><div class="tool-icon">${icon(['globe','layers','radar','compass','grid','grid','grid','branch','target'][i])}</div>${pill(i<3?'ورودی':i<8?'تطبیق':'جهت‌گیری','blue')}</div><h3>${title}</h3><p>${({efe:'آیا به فرصت‌ها و تهدیدها خوب پاسخ می‌دهیم؟',ife:'قوت‌ها و ضعف‌های ما چه تصویری می‌سازند؟',cpm:'در عوامل موفقیت صنعت، نسبت به رقبا کجاییم؟',space:'چه جهت کلی با وضعیت ما تناسب دارد؟',bcg:'بین واحدهای سبد کجا سرمایه‌گذاری کنیم؟',ie:'ترکیب ارزیابی درونی و بیرونی چه می‌گوید؟',ge:'جذابیت صنعت و قدرت واحدها را چگونه مقایسه کنیم؟',ansoff:'در کدام ترکیب بازار و محصول رشد کنیم؟',grand:'موقعیت رقابتی و رشد بازار چه جهت‌هایی می‌سازند؟'})[key]}</p><div class="flex between">${link('باز کردن '+icon('left'),'matrices/'+key)}${pill('داده نمونه')}</div></article>`).join('')}</div><div class="mt">${guide('برای تصمیم نهایی، نتایج را با جریان نقدی، ریسک و امکان‌پذیری ترکیب کنید. هیچ ماتریسی به‌تنهایی حکم رشد یا خروج نمی‌دهد.')}</div>`;}
function factorMatrix(type){const collection=type==='efe'?'external':'internal',rows=state[collection],valid=validWeights(rows),total=weightedScore(rows);return heading(matrixNames[type],'وزن‌ها درصدی هستند. داده‌ها نمونه‌اند؛ برای هر عامل یک شاهد و رتبه مستدل ثبت کنید.',button(icon('plus')+' افزودن عامل','add','primary',`data-collection="${collection}"`)+link('مقایسه گزینه‌ها','qspm','btn'))+
  guide(type==='efe'?'رتبه EFE: پاسخ شرکت ۱=ضعیف تا ۴=عالی؛ حتی برای تهدید می‌تواند ۴ باشد.':'رتبه IFE: ضعف عمده ۱، ضعف جزئی ۲، قوت جزئی ۳، قوت عمده ۴.')+
  `<div class="grid cols-3 mb">${metric('امتیاز وزنی',valid?n(total,2):'نامعتبر','از ۴','پس از کنترل جمع وزن‌ها',type)}${metric('مجموع وزن‌ها',n(sum(rows.map(r=>r.weight)))+'٪','','باید دقیقاً ۱۰۰٪ باشد')}${metric('عوامل ثبت‌شده',n(rows.length),'عامل','قابل‌ویرایش و مستند')}</div>`+
  (!valid?guide('جمع وزن‌ها برابر ۱۰۰٪ نیست. امتیاز نهایی و تحلیل IE/QSPM تا اصلاح وزن‌ها معتبر نیستند.','error'):'')+
  `<section class="panel flat"><div class="table-wrap"><table class="data-table"><thead><tr><th>عامل و منبع</th><th>نوع</th><th>وزن ٪</th><th>رتبه ${hint(type)}</th><th>امتیاز وزنی</th><th>ویرایش</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title-cell"><strong>${e(r.title)}</strong><small>${e(r.source)}</small></td><td>${pill(r.type,['قوت','فرصت'].includes(r.type)?'green':'orange')}</td><td><input type="number" min="0" max="100" step="1" value="${r.weight}" data-factor="${r.id}" data-collection="${collection}" data-field="weight" aria-label="وزن ${e(r.title)}"></td><td><select data-factor="${r.id}" data-collection="${collection}" data-field="rating" aria-label="رتبه ${e(r.title)}">${(type==='ife'?(r.type==='قوت'?[3,4]:[1,2]):[1,2,3,4]).map(v=>`<option value="${v}" ${v===r.rating?'selected':''}>${n(v)}</option>`).join('')}</select></td><td><span class="num">${n(r.weight*r.rating/100,2)}</span></td><td>${button(icon('edit'),'edit','small',`data-collection="${collection}" data-id="${r.id}" aria-label="ویرایش ${e(r.title)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>وزن اهمیت در صنعت است؛ رتبه وضعیت شرکت</span><strong>${valid?'✓ وزن‌ها معتبرند':'وزن‌ها نیاز به اصلاح دارند'}</strong></div></section><div class="mt">${panel('تفسیر محتاطانه',`<p class="small">${valid?`امتیاز ${n(total,2)} در مدل ۱ تا ۴ است. مقدار ۲٫۵ نقطه میانی است، نه مرز قطعی موفقیت. کیفیت شاهد، حساسیت وزن‌ها و اقدام بعدی مهم‌تر از یک عدد هستند.`:'ابتدا وزن‌ها را اصلاح کنید، سپس نتیجه را بخوانید.'}</p>${link('ثبت برداشت یا فرضیه','journal','btn soft mt')}`)}</div>`;
}
function matrixDetail(){if(['efe','ife'].includes(sub))return factorMatrix(sub);if(sub==='cpm')return industry();const products=state.products;
  const tabs=`<div class="tabs">${['space','bcg','ie','ge','ansoff','grand'].map(k=>link(k==='grand'?'Grand':k.toUpperCase(),'matrices/'+k,'tab '+(sub===k?'active':''))).join('')}</div>`;
  let body='';
  if(sub==='space'){const result=space(state.space);body=guide('هر بُعد میانگین سه مؤلفه نمونه است. با تغییر ورودی، بردار و جهت‌گیری دوباره محاسبه می‌شوند.')+`<div class="grid cols-2">${panel('بردار جهت‌گیری',spaceChart(result)+`<div class="flex between">${pill('جهت نمونه: '+result.posture,'blue')}<span class="small">X: ${n(result.x,2)} · Y: ${n(result.y,2)}</span></div>`,'','space')}${panel('امتیازدهی ابعاد',Object.entries(state.space).map(([key,vals])=>`<h3>${({FS:'قدرت مالی',IS:'قدرت صنعت',CA:'مزیت رقابتی',ES:'ثبات محیط'})[key]} · ${key}</h3><div class="grid cols-3 mb">${vals.map((v,i)=>`<label class="field"><span>${({FS:['نقدینگی','بازده سرمایه','دسترسی مالی'],IS:['رشد','پتانسیل سود','موانع ورود'],CA:['سهم بازار','کیفیت','وفاداری'],ES:['نوسان هزینه','تغییر فناوری','فشار رقابت']})[key][i]}</span><input type="number" min="${key==='FS'||key==='IS'?1:-6}" max="${key==='FS'||key==='IS'?6:-1}" step="1" value="${v}" data-space="${key}" data-index="${i}"></label>`).join('')}</div>`).join(''))}</div>`;}
  if(sub==='bcg'){body=guide('محور سهم نسبی از چپ به راست نزولی و لگاریتمی است؛ اندازه حباب تابع درآمد نمونه است. هر واحد را با هم‌افزایی و سودآوری بررسی کنید.')+`<div class="grid wide-left">${panel('سبد رشد–سهم',bcgChart(products,state.bcgThreshold),'','bcg')}${panel('واحدهای نمونه',products.map((p,i)=>`<div class="list-row"><span class="number-chip">${n(i+1)}</span><div><strong>${e(p.title)}</strong><p>سهم نسبی ${n(p.share,2)} · رشد ${n(p.growth)}٪</p></div>${button(icon('edit'),'edit','small',`data-collection="products" data-id="${p.id}" aria-label="ویرایش ${e(p.title)}"`)}</div>`).join('')+`<label class="field mt"><span>مرز رشد بازار در این کارگاه ٪</span><input type="number" min="0" max="100" value="${state.bcgThreshold}" data-setting="bcgThreshold"></label>`)}</div>`;}
  if(sub==='ie'){const valid=validWeights(state.external)&&validWeights(state.internal);const ife=weightedScore(state.internal),efe=weightedScore(state.external),result=iePosition(ife,efe);body=guide('ستون‌ها از چپ: قوت داخلی قوی، متوسط، ضعیف. ردیف‌ها از بالا: پاسخ خارجی قوی، متوسط، ضعیف.')+(valid?'':guide('وزن‌های EFE یا IFE معتبر نیستند؛ هیچ خانه‌ای انتخاب نمی‌شود.','error'))+`<div class="grid cols-2">${panel('ماتریس ۹ خانه‌ای',`<div class="ie-grid">${Array.from({length:9},(_,i)=>`<div class="ie-cell ${valid&&result.cell===i+1?'selected':''}">${n(i+1)}<small>${[0,1,3].includes(i)?'رشد و ساخت':[2,4,6].includes(i)?'حفظ و نگهداری':'برداشت / واگذاری'}</small></div>`).join('')}</div>`,'','ie')}${panel('موقعیت شرکت',`<div class="result-big">${valid?result.action:'نیاز به اصلاح'}</div><p class="small">IFE: ${n(ife,2)} · EFE: ${n(efe,2)}</p><p class="small mt">از ورودی‌های زنده استفاده می‌شود. عدد نزدیک مرز را با حساسیت وزن‌ها بررسی کنید.</p><div class="flex mt">${link('اصلاح EFE','matrices/efe','btn')}${link('اصلاح IFE','matrices/ife','btn')}</div>`)}</div>`;}
  if(sub==='ge'){body=guide('این نمایش از امتیازهای تجمیعی کارگاهی ۱ تا ۵ استفاده می‌کند؛ امتیاز قطعی جذابیت صنعت نیست. در نسخه داده واقعی، ریز عوامل و وزن‌ها باید مستند شوند.')+panel('جذابیت صنعت × قدرت کسب‌وکار',`<div class="ie-grid">${Array.from({length:9},(_,i)=>{const row=Math.floor(i/3),col=i%3;const bin=v=>v>=3.67?0:v>=2.33?1:2;return `<div class="ie-cell ge-cell"><small>${['جذابیت بالا','جذابیت متوسط','جذابیت پایین'][row]} / ${['قدرت بالا','قدرت متوسط','قدرت پایین'][col]}</small>${products.filter(p=>bin(p.attraction)===row&&bin(p.strength)===col).map(p=>`<span>${e(p.title)}</span>`).join('')}</div>`}).join('')}</div><div class="mt flex wrap">${products.map(p=>button(e(p.title)+' · ویرایش','edit','small',`data-collection="products" data-id="${p.id}"`)).join('')}</div>`);}
  if(sub==='ansoff'){body=panel('چهار مسیر رشد',`<div class="swot-grid">${[['نفوذ در بازار','محصول فعلی / بازار فعلی','افزایش تکرار خرید مشتریان فعلی'],['توسعه بازار','محصول فعلی / بازار جدید','پایلوت مشتریان سازمانی'],['توسعه محصول','محصول جدید / بازار فعلی','اشتراک برای مشتریان موجود'],['تنوع','محصول جدید / بازار جدید','ورود به محصول و بخش جدید؛ داده کافی نداریم']].map(([t,m,d])=>`<div class="outline-card"><span class="label">${m}</span><h2 class="mt">${t}</h2><p class="small mt">${d}</p>${button('ثبت یک گزینه از این مسیر','add','soft small mt','data-collection="swot"')}</div>`).join('')}</div>`)+guide('آنسوف طبقه‌بندی جهت رشد است. ریسک تنوع اغلب بالاتر است؛ موفقیت به تناسب قابلیت و اقتصاد مسیر وابسته است.');}
  if(sub==='grand'){body=guide('این ماتریس کیفی است: قدرت رقابتی و رشد بازار را ابتدا با شاهد تعریف کنید. هر خانه فقط خانواده گزینه‌ها را پیشنهاد می‌کند.')+panel('جهت‌های کلان',`<div class="swot-grid">${[['رقابت قوی / رشد بالا','نفوذ، توسعه بازار و محصول'],['رقابت ضعیف / رشد بالا','تقویت رقابت، همکاری یا اصلاح'],['رقابت ضعیف / رشد پایین','بازسازی، کاهش مقیاس یا واگذاری'],['رقابت قوی / رشد پایین','تنوع مرتبط و استفاده از جریان نقد']].map(([t,d])=>`<div class="outline-card"><h3>${t}</h3><p class="small mt">${d}</p>${link('ارزیابی گزینه‌ها','qspm','btn small mt')}</div>`).join('')}</div>`);}
  return heading(matrixNames[sub]||'آزمایشگاه','مدل را برای طرح سؤال بهتر به کار ببرید؛ انتخاب نهایی به شواهد و منابع نیاز دارد.',link('همه ابزارها','matrices','btn'))+tabs+body;
}
function swot(){const groups=[['قوت','internal','strength','قوت‌ها'],['ضعف','internal','weak','ضعف‌ها'],['فرصت','external','opportunity','فرصت‌ها'],['تهدید','external','threat','تهدیدها']];return heading('از تحلیل، گزینه رشد بسازید.','هر گزینه باید مشخص، محدود و قابل‌آزمون باشد؛ نه فقط «افزایش فروش».',button(icon('plus')+' گزینه جدید','add','primary','data-collection="swot"'))+`<div class="swot-grid">${groups.map(([type,col,cls,title])=>`<section class="swot-block ${cls}"><header><strong>${title}</strong>${link('ویرایش','matrices/'+(col==='internal'?'ife':'efe'))}</header><div><ul>${state[col].filter(r=>r.type===type).slice(0,4).map(r=>`<li>${e(r.title)}</li>`).join('')}</ul></div></section>`).join('')}</div><div class="mt">${panel('تطبیق عوامل · TOWS',`<div class="grid cols-2">${state.swot.map(s=>`<article class="outline-card"><div class="flex between">${pill(s.type,'blue')}${button(icon('edit'),'edit','small',`data-collection="swot" data-id="${s.id}" aria-label="ویرایش گزینه"`)}</div><h3 class="mt">${e(s.title)}</h3><p class="small mt">${e(s.detail)}</p></article>`).join('')}</div>`)}</div><div class="mt flex between">${link('قدم بعد: مقایسه گزینه‌ها '+icon('left'),'qspm','btn primary')}${link('مسیرهای رشد آنسوف','matrices/ansoff','btn')}</div>`;}
function qspmPage(){const scores=qspm(state.external,state.internal,state.qScores);const winner=scores?scores.indexOf(Math.max(...scores)):-1;return heading('تصمیم خوب، منطق قابل‌دیدن دارد.','سه گزینه نمونه را با عوامل یکسان مقایسه کنید؛ جذابیت، امکان‌پذیری و ریسک را جدا بخوانید.',button('ثبت جمع‌بندی تصمیم','add','primary','data-collection="journal"'))+
guide('وزن خارجی و داخلی هرکدام ۱۰۰٪ است (جمع کلی ۲۰۰٪). AS نمونه از ۱ تا ۴؛ عامل نامرتبط برای همه گزینه‌ها کنار گذاشته می‌شود. امتیاز عددی پیشنهاد نسبی است، نه انتخاب خودکار.')+
`<div class="grid cols-3 mb">${state.options.map((o,i)=>`<article class="panel"><div class="flex between">${pill('گزینه '+o.id,i===winner?'green':'blue')}${button(icon('edit'),'edit','small',`data-collection="options" data-id="${o.id}" aria-label="ویرایش ${e(o.title)}"`)}</div><h2 class="mt">${e(o.title)}</h2><p class="small mt">${e(o.detail)}</p><div class="result-big">${scores?n(scores[i],2):'—'} <span class="small muted">امتیاز QSPM</span></div><span class="small muted">هزینه تخمینی ${n(o.cost)} میلیون تومان</span>${i===winner?'<p class="small mt" style="color:var(--green)">جذاب‌ترین در امتیازدهی فعلی؛ بررسی ریسک و منابع لازم است.</p>':''}</article>`).join('')}</div>`+
(!scores?guide('وزن‌ها معتبر نیستند؛ ابتدا EFE و IFE را اصلاح کنید.','error'):'')+
panel('امتیازدهی عوامل',`<div class="table-wrap"><table class="data-table"><thead><tr><th>عامل</th><th>وزن ٪</th><th>مرتبط</th>${state.options.map(o=>`<th>${e(o.title)} · AS ${hint('qspm')}</th><th>TAS</th>`).join('')}</tr></thead><tbody>${[['عوامل خارجی',state.external],['عوامل داخلی',state.internal]].map(([title,rows])=>`<tr><td colspan="9" style="background:#f1f5fc;font-weight:600">${title} · جمع وزن ${n(sum(rows.map(r=>r.weight)))}٪</td></tr>${rows.map(r=>{const q=state.qScores[r.id];return `<tr><td class="title-cell">${e(r.title)}</td><td>${n(r.weight)}</td><td><input type="checkbox" ${q.relevant?'checked':''} data-q-relevant="${r.id}" aria-label="ارتباط ${e(r.title)}"></td>${[0,1,2].map(i=>`<td><select data-q-score="${r.id}" data-index="${i}" ${q.relevant?'':'disabled'} aria-label="جذابیت ${e(state.options[i].title)} نسبت به ${e(r.title)}">${[1,2,3,4].map(v=>`<option value="${v}" ${q.as[i]===v?'selected':''}>${n(v)}</option>`).join('')}</select></td><td>${q.relevant?n(r.weight*q.as[i]/100,2):'—'}</td>`).join('')}</tr>`}).join('')}`).join('')}</tbody></table></div>`,'','qspm')+
`<div class="grid cols-2 mt">${panel('SAF · کنترل کیفیت گزینه',`<div class="table-wrap"><table class="data-table"><thead><tr><th>گزینه</th><th>تناسب</th><th>پذیرش</th><th>امکان‌پذیری</th></tr></thead><tbody>${state.options.map(o=>`<tr><td>${e(o.title)}</td><td>${n(o.fit)} / ۵</td><td>${n(o.accept)} / ۵</td><td>${n(o.feasible)} / ۵</td></tr>`).join('')}</tbody></table></div><p class="small mt">این ارزیابی کارگاهی جدا از QSPM است. برای تغییر، گزینه را ویرایش کنید؛ میانگین این سه را به‌عنوان «احتمال موفقیت» تفسیر نکنید.</p>`)}${panel('پیش از تعهد',listLink('آیا نقدینگی کافی داریم؟','محاسبات اقتصادی و NPV','finance','chart')+listLink('اگر فرض‌ها عوض شوند؟','تست حساسیت','scenarios','compass')+listLink('چه کسی اجرا می‌کند؟','ابتکار، بودجه و مالک','execution','kanban'))}</div>`;
}
function finance(){const f=financials(state.fin),v=state.investment,value=npv(v.initial,v.flows,v.rate/100),rate=irr(v.initial,v.flows);return heading('رشد باید از نظر اقتصادی هم معنا داشته باشد.','مبالغ میلیون تومان‌اند. نسبت‌ها مربوط به ماه نمونه؛ CAGR و سرمایه‌گذاری جداگانه سالانه‌اند.',button(icon('edit')+' ویرایش ارقام','financeEdit','primary'))+
`<div class="grid cols-4 mb">${metric('بازده دارایی‌ها',pct(f.roa),'ماهانه','میانگین دارایی ابتدا و انتها','roa')}${metric('بازده حقوق سهام',pct(f.roe),'ماهانه','حقوق ثابت در دوره فرض شده','roe')}${metric('هزینه جذب مشتری',n(f.cac,2),'میلیون تومان','در ماه نمونه','cac')}${metric('ارزش طول عمر',n(f.ltv,2),'میلیون تومان','برآورد حاشیه مشارکت','ltv')}</div>`+
`<div class="grid cols-2">${panel('اقتصاد ماه نمونه',bars(['درآمد','هزینه متغیر','هزینه ثابت','سود عملیاتی'],[state.fin.revenue,state.fin.variable,state.fin.fixed,f.operating],['#2459ed','#a9bbec','#d2dcf4','#209c6d'])+`<div class="list-row"><div><p>نقطه سربه‌سر ریالی</p><strong>${n(f.breakEven)} میلیون تومان در ماه</strong></div></div><div class="list-row"><div><p>رشد مرکب فروش سالانه ${hint('cagr')}</p><strong>${pct(f.cagr)}</strong></div></div><div class="list-row"><div><p>سهم بازار ماه نمونه</p><strong>${pct(f.marketShare)}</strong></div></div>`)}${panel('جریان نقدی و جذب',`<div class="result-big">${n(state.fin.cash)} <span class="small muted">میلیون تومان موجودی نقد</span></div><p class="small">خالص جریان نقدی ماه نمونه: ${n(state.fin.cashFlow)} میلیون تومان.</p><div class="list-row"><div><p>Runway</p><strong>${f.runway===null?'با جریان نقدی غیرمنفی، در این مدل موضوعیت ندارد':n(f.runway)+' ماه'}</strong></div></div><div class="list-row"><div><p>LTV / CAC</p><strong>${n(ratio(f.ltv,f.cac),2)} برابر</strong></div></div><div class="list-row"><div><p>دوره بازگشت CAC</p><strong>${n(ratio(f.cac,state.fin.aov*state.fin.frequency*(f.contributionMargin??0)),2)} ماه</strong></div></div><p class="small mt">نسبت‌ها با یک تعریف ثابت و کوهورت واقعی بررسی شوند. هدف خوب/بد جهانی و یکسانی برای همه صنایع وجود ندارد.</p>`)}</div>`+
`<div class="mt">${panel('ارزیابی سرمایه‌گذاری · دوره سالانه',`<div class="grid cols-2"><form id="investment-form"><div class="form-grid">${field('سرمایه‌گذاری اولیه · میلیون','initial',v.initial,'number','min="1" required step="any"')}${field('نرخ تنزیل سالانه ٪','rate',v.rate,'number','min="0" max="200" required step="any"')}<label class="field full"><span>جریان نقدی سال‌های ۱، ۲ و ۳ · میلیون تومان</span><input name="flows" dir="ltr" value="${v.flows.join(', ')}" required placeholder="450, 600, 750"><small>با ویرگول جدا کنید. جریان غیرمتعارف برای NPV پذیرفته می‌شود، برای IRR نه.</small></label></div>${button('محاسبه دوباره','calculate','primary','type="submit"')}</form><div><div class="grid cols-2">${metric('ارزش فعلی خالص',n(value,2),'میلیون تومان','مبنا: پایان هر سال','npv')}${metric('نرخ بازده داخلی',pct(rate),'سالانه',rate===null?'IRR یکتا قابل‌گزارش نیست':'فقط جریان نقدی متعارف','irr')}</div><p class="small mt">${value>=0?'NPV با فرض‌های فعلی مثبت است؛ این نتیجه شرطی است.':'NPV با فرض‌های فعلی منفی است؛ گزینه و فرض‌های آن را بازبینی کنید.'}</p><div class="mt">${link('آزمون حساسیت فرض‌ها','scenarios','btn')}</div></div></div>`,'','npv')}</div>`;
}
function scenarios(){const f=state.fin,s=state.scenario,result=scenarioResult(f.revenue,f.variable/f.revenue,f.fixed,s.growth,s.inflation);const sets=[['کاهش تقاضا',-10,20],['ادامه روند',12,10],['رشد کنترل‌شده',25,5]],profits=sets.map(([,g,i])=>scenarioResult(f.revenue,f.variable/f.revenue,f.fixed,g,i).profit);return heading('برای یک آینده برنامه نریزید.','عدم‌قطعیت‌ها را به سناریو، نشانه هشدار و پاسخ قابل‌اجرا تبدیل کنید.',button('ثبت فرضیه سناریو','add','primary','data-collection="journal"'))+guide('این نمودار مالی یک آزمون حساسیت ساده است. رشد، حجم را با قیمت ثابت تغییر می‌دهد و تورم فقط هزینه متغیر واحد را؛ هزینه ثابت در این آزمون ثابت است.')+`<div class="grid cols-2">${panel('اگر تقاضا و هزینه تغییر کنند؟',`<label class="field"><span>رشد حجم فروش ٪ <strong style="margin-right:auto">${n(s.growth)}٪</strong></span><input type="range" min="-40" max="60" step="1" value="${s.growth}" data-scenario="growth" aria-label="رشد حجم فروش"></label><label class="field"><span>رشد هزینه متغیر واحد ٪ <strong style="margin-right:auto">${n(s.inflation)}٪</strong></span><input type="range" min="-10" max="60" step="1" value="${s.inflation}" data-scenario="inflation" aria-label="رشد هزینه"></label><div class="result-big ${result.profit<0?'negative':''}">${n(result.profit)} <span class="small muted">سود عملیاتی ماه بعد · میلیون</span></div><p class="small">فروش: ${n(result.revenue)} · هزینه ثابت: ${n(f.fixed)}</p>`,'','scenario')}${panel('سه حالت مالی نمونه',bars(sets.map(s=>s[0]),profits,['#d28a74','#91adee','#2459ed'])+'<p class="small">اعداد، پیش‌بینی بازار یا احتمال وقوع نیستند. تفاوت‌ها را با فرضیات ثبت‌شده بسنجید.</p>')}</div><div class="mt">${panel('چهار آینده متفاوت · دو عدم‌قطعیت',`<div class="scenario-grid">${[['رشد تقاضا / ثبات تأمین','گسترش مرحله‌ای؛ پایش ظرفیت و کیفیت'],['رشد تقاضا / بی‌ثباتی تأمین','قرارداد جایگزین و محدودیت تعهد سفارش'],['افت تقاضا / ثبات تأمین','آزمایش پیشنهاد ارزش و کاهش هزینه جذب'],['افت تقاضا / بی‌ثباتی تأمین','حفظ نقدینگی، توقف توسعه و بازبینی سبد']].map(([t,d])=>`<article class="scenario-card"><h3>${t}</h3><p>${d}</p><div class="mt">${link('پاسخ‌ها و محرک‌های ریسک','risks','btn small')}</div></article>`).join('')}</div><p class="small mt">برای سناریوی واقعی: روایت علّی، نشانه ورود به آینده، اقدام بدون پشیمانی و مسئول پاسخ را بنویسید.</p>`)}</div>`;}
function execution(){return heading('استراتژی را به حرکت تبدیل کنید.','هر ابتکار به یک هدف، مسئول، بودجه و معیار پایان متصل است.',button(icon('plus')+' ابتکار جدید','add','primary','data-collection="initiatives"'))+
`<div class="grid cols-3 mb">${metric('بودجه برنامه',n(sum(state.initiatives.map(p=>p.budget))),'میلیون تومان','جمع بودجه ابتکارها')}${metric('ابتکارهای فعال',n(state.initiatives.filter(p=>p.status==='در اجرا').length),'ابتکار','قابل‌ویرایش')}${metric('تکمیل‌شده',n(state.initiatives.filter(p=>p.status==='تکمیل‌شده').length),'ابتکار','پیشرفت، خوداظهاری تیم است')}</div>`+
`<div class="kanban">${['برای شروع','در اجرا','تکمیل‌شده'].map(status=>`<section class="kanban-col"><header><strong>${status}</strong>${pill(state.initiatives.filter(p=>p.status===status).length)}</header>${state.initiatives.filter(p=>p.status===status).map(p=>`<article class="task-card">${pill(state.objectives.find(o=>o.id===p.objective)?.title||'هدف تعریف نشده','blue')}<h3>${e(p.title)}</h3><p>${e(p.detail)}</p><div class="flex between"><span class="small muted">پیشرفت</span><strong class="small">${n(p.progress)}٪</strong></div>${progressBar(p.progress)}<div class="flex between"><span class="avatar sm">${e(translate(p.owner).slice(0,1))}</span><span class="small muted">${e(p.owner)}</span><span class="small muted">${n(p.budget)} م.</span></div><div class="small muted mt">موعد: ${e(p.due)}</div>${button('ویرایش و تغییر وضعیت','edit','small',`data-collection="initiatives" data-id="${p.id}"`)}</article>`).join('')||'<p class="small">ابتکاری در این ستون نیست.</p>'}</section>`).join('')}</div><div class="mt">${panel('برنامه ۳۰ / ۶۰ / ۹۰ روزه · نمونه',`<div class="grid cols-3">${[['۳۰ روز','مصاحبه خریدار، نمونه محصول، سقف اعتبار','خروجی: ۵ مشتری پایلوت'],['۶۰ روز','تحویل پایلوت، اندازه‌گیری وصول و کیفیت','خروجی: گزارش حاشیه و رضایت'],['۹۰ روز','تصمیم توسعه یا توقف بر اساس شواهد','خروجی: برنامه فصل بعد']].map(([t,d,r])=>`<div class="outline-card"><span class="pill blue">${t}</span><h3 class="mt">${d}</h3><p class="small mt">${r}</p></div>`).join('')}</div><p class="small mt">نمونه RACI: اجرای پایلوت با فروش؛ پاسخ‌گویی با مدیر استراتژی؛ مشورت مالی و عملیات؛ اطلاع به مدیرعامل.</p>`)}</div>`;}
function scorecard(){return heading('نتیجه‌ها و محرک‌ها را کنار هم ببینید.','کارت امتیازی متوازن؛ هر هدف یک شاخص، مبنا، هدف زمانی و مالک دارد.',button(icon('plus')+' هدف جدید','add','primary','data-collection="objectives"'))+`<div class="grid cols-4 mb">${['مالی','مشتری','فرایند','یادگیری'].map(p=>{const goals=state.objectives.filter(o=>o.perspective===p);return metric(p,n(goals.length),'هدف','منظر کارت امتیازی','bsc')}).join('')}</div>`+panel('هدف، شاخص و شکاف',`<div class="table-wrap"><table class="data-table"><thead><tr><th>هدف / شاخص</th><th>منظر</th><th>مبنا</th><th>واقعی</th><th>هدف</th><th>پیشرفت ${hint('progress')}</th><th>مسئول / موعد</th><th></th></tr></thead><tbody>${state.objectives.map(o=>`<tr><td class="title-cell"><strong>${e(o.title)}</strong><small>${e(o.metric)}</small></td><td>${pill(o.perspective,'blue')}</td><td>${n(o.baseline)}</td><td>${n(o.actual)}</td><td>${n(o.target)}</td><td style="min-width:105px"><span class="small">${n(progress(o.actual,o.baseline,o.target))}٪</span>${progressBar(progress(o.actual,o.baseline,o.target))}</td><td><div class="small">${e(o.owner)}</div><span class="small muted">${e(o.due)}</span></td><td>${button(icon('edit'),'edit','small',`data-collection="objectives" data-id="${o.id}" aria-label="ویرایش هدف"`)}</td></tr>`).join('')}</tbody></table></div>`,'','bsc')+`<div class="grid cols-2 mt">${panel('نقشه استراتژی · فرضیه خلق ارزش',`<div class="score-map">${['مالی','مشتری','فرایند','یادگیری'].map((p,i)=>`<div class="map-row"><span class="map-label">${p}</span><a href="#scorecard" class="map-node">${e(state.objectives.find(o=>o.perspective===p)?.title||'هدف این منظر را اضافه کنید')}</a></div>${i<3?'<div class="map-arrow" aria-label="فرضیه اثرگذاری به منظر بالاتر">↑</div>':''}`).join('')}</div><p class="small mt">این ارتباط‌ها فرضیه علّی‌اند؛ با داده، زمان تأخیر و آزمون یادگیری بررسی شوند.</p>`)}${panel('جلسه بازبینی ماهانه',`<div class="stack"><p class="small">۱. چه چیزی تغییر کرده و چرا؟</p><p class="small">۲. انحراف ساختاری است یا موقت؟</p><p class="small">۳. کدام فرضیه نیاز به آزمون دارد؟</p><p class="small">۴. چه چیزی را ادامه، اصلاح یا متوقف می‌کنیم؟</p></div><div class="mt">${button('ثبت تصمیم بازبینی','add','primary','data-collection="journal"')}</div>`)}</div>`;}
function risks(){return heading('ریسک را ببینید، پاسخ را مشخص کنید.','رنگ‌ها اولویت کارگاهی‌اند؛ احتمال و اثر رتبه‌ای جای برآورد خسارت را نمی‌گیرند.',button(icon('plus')+' ریسک جدید','add','primary','data-collection="risks"'))+`<div class="grid wide-left">${panel('فهرست پاسخ‌ها',state.risks.map(r=>`<article class="outline-card mb"><div class="flex between"><h3>${e(r.title)}</h3>${pill('اولویت '+n(r.probability*r.impact),r.probability*r.impact>=16?'red':r.probability*r.impact>=8?'orange':'green')}</div><p class="small mt">پاسخ: ${e(r.response)}</p><p class="small">محرک بازبینی: ${e(r.trigger)}</p><div class="flex between mt"><span class="small muted">${e(r.owner)} · ${e(r.status)}</span>${button('ویرایش پاسخ','edit','small',`data-collection="risks" data-id="${r.id}"`)}</div></article>`).join(''))}${panel('نقشه احتمال × اثر',`<div class="heatmap">${Array.from({length:25},(_,i)=>{const probability=5-Math.floor(i/5),impact=i%5+1,score=probability*impact,rs=state.risks.filter(r=>r.probability===probability&&r.impact===impact);return `<div class="heat-cell ${score>=16?'high':score>=8?'medium':'low'}" title="احتمال ${probability}، اثر ${impact}">${rs.length?rs.map(r=>`<button class="risk-dot" data-action="edit" data-collection="risks" data-id="${r.id}" aria-label="${e(r.title)}">${e(r.id)}</button>`).join(''):n(score)}</div>`}).join('')}</div><div class="flex between mt"><span class="small muted">احتمال: پایین ۱ ← بالا ۵</span><span class="small muted">اثر: ۱ ← ۵</span></div><p class="small mt">مرزهای نمونه: ۱۶ به بالا قرمز، ۸ تا ۱۵ هشدار، پایین‌تر سبز. این رتبه‌ها به معنی احتمال درصدی نیستند.</p>`,'','risk')}</div>`;}
function journal(){const filter=sub||'all',rows=state.journal.filter(r=>filter==='all'||r.kind===filter);return heading('حافظه تصمیم‌های شرکت.', 'واقعیت، فرضیه و تصمیم را از هم جدا کنید؛ منطق و شرط بازبینی را نگه دارید.',button(icon('plus')+' ثبت جدید','add','primary','data-collection="journal"'))+`<div class="tabs">${[['all','همه موارد'],['تصمیم','تصمیم‌ها'],['فرضیه','فرضیه‌ها'],['شاهد','شواهد']].map(([k,t])=>link(t,'journal/'+k,'tab '+(filter===k?'active':''))).join('')}</div>`+`<div class="stack">${rows.map(r=>`<article class="panel"><div class="flex between"><div class="flex">${pill(r.kind,r.kind==='تصمیم'?'blue':r.kind==='فرضیه'?'purple':'green')}<h3>${e(r.title)}</h3></div>${button(icon('edit'),'edit','small',`data-collection="journal" data-id="${r.id}" aria-label="ویرایش ثبت"`)}</div><p class="small mt">${e(r.detail)}</p><p class="small mt">شاهد / منبع: ${e(r.evidence)}</p><div class="flex between mt"><span class="small muted">${e(r.owner)} · بازبینی ${e(r.due)}</span>${statusPill(r.status)}</div></article>`).join('')||'<div class="blank"><h2>هنوز موردی ثبت نشده.</h2><p>اولین فرضیه یا تصمیم را با منبع و موعد بازبینی بنویسید.</p></div>'}</div>`;}
function reports(){const scores=qspm(state.external,state.internal,state.qScores),f=financials(state.fin);return heading('استراتژی را قابل‌ارائه کنید.','گزارش زنده از داده‌های همین مرورگر؛ آماده چاپ یا ذخیره PDF.',button(icon('download')+' چاپ / PDF','print','primary')+button('خروجی JSON','export'))+`<article class="report"><div class="flex between"><div><span class="label">گزارش مدیریتی · نمونه آموزشی</span><h1>${e(state.org.name)}؛ از شناخت تا اقدام</h1></div><div class="brand-mark">${BRAND_MARK}</div></div><p class="small">همه ارقام فرضی‌اند. تاریخ تهیه: ${new Date().toLocaleDateString(locale())} · مالی: ماه نمونه · میلیون تومان</p><h2>مسئله اصلی</h2><p>${e(state.org.challenge)}</p><h2>وضعیت امروز</h2><ul><li>فروش ${n(state.fin.revenue)}؛ حاشیه ناخالص ${pct(f.grossMargin)}؛ ROA ماهانه ${pct(f.roa)}</li><li>امتیاز EFE: ${validWeights(state.external)?n(weightedScore(state.external),2):'وزن نامعتبر'}؛ IFE: ${validWeights(state.internal)?n(weightedScore(state.internal),2):'وزن نامعتبر'}</li></ul><h2>گزینه‌های بررسی‌شده</h2>${scores?bars(state.options.map(o=>o.title),scores):guide('وزن‌ها معتبر نیستند؛ ابتدا EFE و IFE را اصلاح کنید.','error')}<p class="small">QSPM مقایسه جذابیت نسبی است، نه ضمانت. امکان‌پذیری، هزینه و ریسک جداگانه بررسی می‌شوند.</p><h2>اولویت‌های اجرای ۹۰ روزه</h2><ul>${state.initiatives.map(p=>`<li>${e(p.title)} · مسئول ${e(p.owner)} · بودجه ${n(p.budget)} · وضعیت ${e(p.status)}</li>`).join('')}</ul><h2>ریسک و شرط بازبینی</h2><ul>${state.risks.filter(r=>r.probability*r.impact>=16).map(r=>`<li>${e(r.title)}؛ شرط: ${e(r.trigger)}؛ پاسخ: ${e(r.response)}</li>`).join('')}</ul><h2>دفتر تصمیم</h2><ul>${state.journal.filter(r=>r.kind==='تصمیم').map(r=>`<li>${e(r.title)}: ${e(r.detail)}</li>`).join('')}</ul><h2>یادداشت مدیر استراتژی</h2><label class="field"><textarea data-setting="notes" placeholder="منطق انتخاب، کارهایی که انجام نمی‌دهیم، منابع و موعد بازبینی را ثبت کنید.">${e(state.notes)}</textarea></label><p class="small">پروتوتایپ فرانت‌اند؛ فاقد اتصال ERP، تأیید حقوقی یا توصیه خودکار سرمایه‌گذاری.</p></article>`;}
function learn(){if(help[sub]){const h=help[sub],source=sources.find(s=>s.id===h.source);return heading(h.title,'یادگیری در جریان کار؛ تعریف، محاسبه، مثال و محدودیت.',link('همه موضوع‌ها','learn','btn'))+panel('این مفهوم چه می‌گوید؟',`<div class="lesson-content"><h2>${e(h.simple)}</h2><h3>فرمول یا روش</h3><div class="formula" dir="rtl">${e(h.formula)}</div><h3>یک مثال</h3><p>${e(h.example)}</p><h3>چگونه بخوانیم؟</h3><p>${e(h.interpretation)}</p><h3>کجا ممکن است اشتباه کنیم؟</h3>${guide(e(h.caution),'warning')}<h3>تمرین کوتاه</h3><p>با داده نمونه، یک ورودی را تغییر دهید و قبل از محاسبه حدس بزنید نتیجه چگونه تغییر می‌کند. سپس توضیح دهید چه تصمیمی از این تغییر می‌گیرید.</p><a class="source-link" href="${source?.url||'#learn'}" target="_blank" rel="noopener noreferrer">${e(source?.title||'منبع')}</a><div class="flex mt">${link('آزمایش در پنل',conceptRoutes[sub]||'overview','btn primary')}</div></div>`);}
  if(sub==='sources')return heading('پایه علمی و محدودیت‌ها.','چارچوب‌های کلاسیک به‌همراه منابع جدید اجرا و آینده‌نگری؛ بازبینی منبع: اکتبر ۲۰۲۶.',link('کتابخانه','learn','btn'))+panel('منابع بررسی‌شده',sources.map(s=>`<div class="source-card"><div><strong>${e(s.title)}</strong><p>${e(s.note)}</p></div><a class="btn small" href="${s.url}" target="_blank" rel="noopener noreferrer">باز کردن منبع ${icon('link')}</a></div>`).join(''))+guide('نمونه یک ابزار آموزشی پشتیبان تصمیم است. هیچ کتاب یا مدرک MBA/DBA موفقیت تجاری را تضمین نمی‌کند. امتیازهای داخلی، آستانه‌ها و فرض‌ها از واقعیت قابل‌راستی‌آزمایی جدا هستند.');
  return heading('هر ابزار، یک درس کوتاه.', 'کنار هر مفهوم ! را لمس کنید؛ یا از اینجا وارد درس کامل شوید.',link('منابع علمی','learn/sources','btn'))+`<div class="grid cols-3">${Object.entries(help).map(([k,h])=>`<article class="panel tool-card"><div class="tool-icon">${icon('cap')}</div><h3>${h.title}</h3><p>${h.simple}</p>${link('یادگیری و مثال '+icon('left'),'learn/'+k)}</article>`).join('')}</div>`;
}
function settings(){return heading('فضای کار شما.', 'ظاهر، زبان و راهنمای آموزشی را مطابق سبک کار خود تنظیم کنید.')+
`<section class="panel learning-control" aria-labelledby="learning-control-title"><div class="learning-control-top"><div class="learning-control-copy"><span class="learning-control-mark">${icon('cap')}</span><div><h2 id="learning-control-title">آموزش در اپ</h2><p class="small">${state.learning?'آموزش‌ها روشن است. برای پنهان‌کردن دکمه‌ها و درس‌ها، کلید را خاموش کنید.':'آموزش‌ها خاموش است. برای نمایش راهنمای صفحه‌ها، مفاهیم و کتابخانه، کلید را روشن کنید.'}</p></div></div><label class="setting-switch" title="${state.learning?'خاموش‌کردن آموزش':'فعال‌کردن آموزش'}"><input type="checkbox" role="switch" aria-label="فعال‌سازی آموزش در اپ" aria-describedby="learning-control-title" data-setting="learning" ${state.learning?'checked':''}><span class="switch-track" aria-hidden="true"></span><span class="switch-status">${state.learning?'آموزش: روشن':'آموزش: خاموش'}</span></label></div><div class="learning-control-foot">${pill(state.learning?'آموزش فعال است':'حالت حرفه‌ای',state.learning?'blue':'')}<p class="small">هشدارهای اعتبار داده و محاسبات در هر دو حالت نمایش داده می‌شوند.</p></div></section><div class="grid cols-2 mt">${panel('ظاهر و زبان',`<div class="settings-preview">${strategyIllustration()}<div><h3>یک محیط، دو سبک کار</h3><p class="small">آموزش در جریان کار، یا فضای حرفه‌ای متمرکز.</p></div></div><label class="field"><span>تم محیط</span><select data-preference="theme">${[['light','روشن'],['dark','تیره'],['system','مطابق سیستم']].map(([v,l])=>`<option value="${v}" ${preferences.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>زبان محیط</span><select data-preference="language"><option value="fa" ${preferences.language==='fa'?'selected':''}>فارسی</option><option value="en" ${preferences.language==='en'?'selected':''}>English</option></select></label><label class="field"><span>حرکت و انیمیشن</span><select data-preference="motion">${[['auto','هماهنگ با تنظیم دستگاه'],['reduced','حرکت کمتر']].map(([v,l])=>`<option value="${v}" ${preferences.motion===v?'selected':''}>${l}</option>`).join('')}</select></label>`)}${panel('سبک کار',`<label class="field"><span>حالت استفاده</span><select data-setting="mode">${options(['company','startup'],state.mode).replace('>company<','>شرکت / تیم استراتژی<').replace('>startup<','>استارتاپ / مسیر ساده<')}</select></label><div class="mt">${button('تغییر مشخصات شرکت','companyEdit')}</div>`)}</div><div class="mt">${panel('حفظ داده و نصب',`<p class="small">${storageAvailable?'تغییرات به‌صورت محلی ذخیره می‌شوند.':'ذخیره محلی در دسترس نیست.'} پاک‌کردن داده مرورگر، اطلاعات را حذف می‌کند. فایل پشتیبان بگیرید.</p><div class="flex wrap mt">${button(icon('download')+' پشتیبان JSON','export')}${button('واردکردن پشتیبان','import')}${button('راهنمای نصب PWA','install','soft')}${button('بازنشانی داده نمونه','reset','danger')}</div>`)}</div>`;}
